/**
 * organization-knowledge-builder.ts — 组织知识库构建器
 *
 * 从诊断报告中提取可复用的组织知识：
 *   - 团队协作模式指纹
 *   - 最佳实践沉淀
 *   - 反模式识别
 *   - 跨团队知识迁移
 *
 * 知识类型：
 *   - pattern       — 协作模式（可复用的结构）
 *   - antipattern   — 反模式（应避免的结构）
 *   - benchmark     — 基准数据（供同行业对比）
 *   - insight       — 洞察（非结构化经验）
 */
export type KnowledgeType = 'pattern' | 'antipattern' | 'benchmark' | 'insight';
export interface OrgKnowledgeEntry {
    id: string;
    type: KnowledgeType;
    /** 知识标题 */
    title: string;
    /** 详细描述 */
    description: string;
    /** 来源团队 ID */
    sourceTeamId: string;
    /** 关联的缝隙维度 */
    dimensions: string[];
    /** 标签 */
    tags: string[];
    /** 证据强度 0-1 */
    evidenceStrength: number;
    /** 适用范围 */
    applicableTo: ('startup' | 'sme' | 'enterprise' | 'tech' | 'non-tech')[];
    /** 创建时间 */
    createdAt: string;
    /** 引用次数（跨团队复用计数） */
    citationCount: number;
    /** 版本（更新时递增） */
    version: number;
}
export interface KnowledgeQuery {
    type?: KnowledgeType;
    dimensions?: string[];
    tags?: string[];
    applicableTo?: OrgKnowledgeEntry['applicableTo'][number];
    keyword?: string;
    minEvidenceStrength?: number;
    limit?: number;
}
export interface KnowledgeStats {
    totalEntries: number;
    byType: Record<KnowledgeType, number>;
    byDimension: Record<string, number>;
    topCited: OrgKnowledgeEntry[];
}
/** 添加组织知识 */
export declare function addKnowledge(entry: Omit<OrgKnowledgeEntry, 'id' | 'citationCount' | 'version' | 'createdAt'>): OrgKnowledgeEntry;
/** 更新或插入知识 */
export declare function upsertKnowledge(id: string, entry: Omit<OrgKnowledgeEntry, 'id' | 'citationCount' | 'version' | 'createdAt'>): OrgKnowledgeEntry;
/** 获取知识条目 */
export declare function getKnowledge(id: string): OrgKnowledgeEntry | null;
/** 查询知识库 */
export declare function queryKnowledge(q?: KnowledgeQuery): OrgKnowledgeEntry[];
/** 引用知识（增加引用计数） */
export declare function citeKnowledge(id: string): boolean;
/** 删除知识 */
export declare function deleteKnowledge(id: string): boolean;
/** 知识库统计 */
export declare function getKnowledgeStats(): KnowledgeStats;
/** 重置知识库（测试用） */
export declare function resetKnowledge(): void;
interface ExtractionInput {
    teamId: string;
    /** 基于诊断发现的维度得分映射 */
    dimensionScores: Record<string, number>;
    /** 关键发现 */
    keyFindings: string[];
    /** 行动建议 */
    recommendations: string[];
    /** 团队规模和类型 */
    teamContext: {
        size: number;
        industry: string;
        stage: 'startup' | 'sme' | 'enterprise';
        isTech: boolean;
    };
}
/** 从诊断结果中自动提取可复用知识 */
export declare function extractFromDiagnosis(input: ExtractionInput): OrgKnowledgeEntry[];
export {};
